 1→import { useEffect, useMemo, useRef } from "react";
 2→
 3→interface DebouncedFunction<A extends unknown[]> {
 4→  (...args: A): void;
 5→  cancel: () => void;
 6→}
 7→
 8→/**
 9→ * `useDebouncedCallback` returns a debounced version of the provided callback
10→ * that automatically cancels pending invocations on unmount.
11→ * @param callback - the function to debounce
12→ * @param delay - debounce delay in milliseconds
13→ * @returns a debounced function with a `.cancel()` method
14→ */
15→export const useDebouncedCallback = <A extends unknown[]>(
16→  callback: (...args: A) => void,
17→  delay: number,
18→): DebouncedFunction<A> => {
19→  // When upgraded to React 19, this could be a useEffectEvent
20→  const callbackRef = useRef(callback);
21→  useEffect(() => {
22→    callbackRef.current = callback;
23→  });
24→
25→  const timeoutRef = useRef<ReturnType<typeof setTimeout>>();
26→
27→  const debouncedFn = useMemo(() => {
28→    const fn = ((...args: A) => {
29→      clearTimeout(timeoutRef.current);
30→      timeoutRef.current = setTimeout(() => {
31→        callbackRef.current(...args);
32→      }, delay);
33→    }) as DebouncedFunction<A>;
34→
35→    fn.cancel = () => {
36→      clearTimeout(timeoutRef.current);
37→    };
38→
39→    return fn;
40→  }, [delay]);
41→
42→  useEffect(() => () => debouncedFn.cancel(), [debouncedFn]);
43→
44→  return debouncedFn;
45→};
46→

  1→import { useCallback, useEffect, useRef } from "react";
  2→import { CharKey, ModifierKey } from "../../constants/keys";
  3→import { arraySymmetricDifference } from "../../utils/array";
  4→
  5→type ShortcutKeys = {
  6→  modifierKeys?: ModifierKey[];
  7→  charKey: CharKey;
  8→};
  9→
 10→export type UseKeyboardShortcutOptions = {
 11→  disabled?: boolean;
 12→  preventDefault?: boolean;
 13→  ignoreFocus?: boolean;
 14→  sendAnalytics?: (data: { name: string; keys: string }) => void;
 15→};
 16→
 17→const INPUT_ELEMENTS = ["INPUT", "TEXTAREA", "SELECT", "BUTTON"];
 18→
 19→/**
 20→ * `useKeyboardShortcut` is a hook that executes a callback when a specific keyboard shortcut is pressed.
 21→ * @param keys - the shortcut keys configuration (modifier keys and character key)
 22→ * @param cb - callback to execute when the shortcut is pressed
 23→ * @param options - configuration options for the shortcut behavior
 24→ */
 25→export const useKeyboardShortcut = (
 26→  keys: ShortcutKeys,
 27→  cb: () => void,
 28→  options: UseKeyboardShortcutOptions = {},
 29→): void => {
 30→  // Validate keys in useEffect to avoid issues during render
 31→  useEffect(() => {
 32→    if (!keys.modifierKeys?.length && !keys.charKey) {
 33→      throw new Error("Must provide at least one key.");
 34→    }
 35→  }, [keys.modifierKeys, keys.charKey]);
 36→
 37→  const cbRef = useRef(cb);
 38→  useEffect(() => {
 39→    cbRef.current = cb;
 40→  }, [cb]);
 41→
 42→  const {
 43→    disabled = false,
 44→    ignoreFocus = false,
 45→    preventDefault = true,
 46→    sendAnalytics,
 47→  } = options;
 48→
 49→  const areExactModifierKeysPressed = (
 50→    event: KeyboardEvent,
 51→    modifierKeys: ModifierKey[],
 52→  ): boolean => {
 53→    const pressedModifierKeys: ModifierKey[] = [
 54→      ...(event.ctrlKey || event.metaKey ? [ModifierKey.Control] : []),
 55→      ...(event.altKey ? [ModifierKey.Alt] : []),
 56→      ...(event.shiftKey ? [ModifierKey.Shift] : []),
 57→    ];
 58→    return (
 59→      arraySymmetricDifference(pressedModifierKeys, modifierKeys).length === 0
 60→    );
 61→  };
 62→
 63→  const handleKeydown = useCallback(
 64→    (event: KeyboardEvent) => {
 65→      const exactModifierKeysPressed = areExactModifierKeysPressed(
 66→        event,
 67→        keys.modifierKeys ?? [],
 68→      );
 69→      const charKeyPressed = event.key === keys.charKey;
 70→
 71→      const shouldExecute =
 72→        ignoreFocus ||
 73→        !INPUT_ELEMENTS.includes((event.target as HTMLElement).tagName);
 74→
 75→      if (exactModifierKeysPressed && charKeyPressed) {
 76→        if (shouldExecute) {
 77→          if (preventDefault) {
 78→            event.preventDefault();
 79→          }
 80→          cbRef.current();
 81→          if (sendAnalytics) {
 82→            sendAnalytics({
 83→              name: "Used Shortcut",
 84→              keys: getPressedKeysAsString(keys),
 85→            });
 86→          }
 87→        }
 88→      }
 89→    },
 90→    [keys, preventDefault, ignoreFocus, sendAnalytics],
 91→  );
 92→
 93→  useEffect(() => {
 94→    if (disabled) {
 95→      document.removeEventListener("keydown", handleKeydown);
 96→    } else {
 97→      document.addEventListener("keydown", handleKeydown);
 98→    }
 99→
100→    return (): void => {
101→      document.removeEventListener("keydown", handleKeydown);
102→    };
103→  }, [handleKeydown, disabled]);
104→};
105→
106→const getPressedKeysAsString = (keys: ShortcutKeys): string => {
107→  const { charKey, modifierKeys } = keys;
108→  const modifierKeysString = modifierKeys?.join("+") ?? "";
109→  const charKeyString = charKey ?? "";
110→  return `${modifierKeysString}${charKeyString}`;
111→};
112→

 1→import { RefObject, useEffect } from "react";
 2→
 3→/**
 4→ * `useOnClickOutside` is a hook that executes a callback when a click is detected outside of the provided refs.
 5→ * @param refs - array of refs to check if the click is outside of
 6→ * @param cb - callback to execute when the click is outside of the refs
 7→ */
 8→export const useOnClickOutside = (
 9→  refs: Array<RefObject<HTMLElement>>,
10→  cb: () => void,
11→): void => {
12→  useEffect(() => {
13→    /**
14→     * `handleClickOutside` executes the callback if a mouse click is detected outside of the target elements.
15→     * @param event - the event that is being listened to
16→     */
17→    function handleClickOutside(event: MouseEvent): void {
18→      const isNotFocused = refs.every(
19→        (ref) => ref.current && !ref.current.contains(event.target as Node),
20→      );
21→      if (isNotFocused) {
22→        cb();
23→      }
24→    }
25→    document.addEventListener("mousedown", handleClickOutside);
26→    return (): void => {
27→      document.removeEventListener("mousedown", handleClickOutside);
28→    };
29→  }, [cb, refs]);
30→};
