 3→/**
 4→ * `usePrevious` is a hook that returns the previous value of a state.
 5→ * @param state - the value to track
 6→ * @returns the previous value of the state
 7→ */
 8→export const usePrevious = <T>(state: T): T | undefined => {
 9→  const ref = useRef<T>();
10→  useEffect(() => {
11→    ref.current = state;
12→  }, [state]);
13→  // This is not correct use of refs, but it's not possible to fix until DEVPROD-14178 is done
14→  // because it throws errors that are not easy to debug.
15→  return ref.current; // eslint-disable-line react-hooks/refs
16→};
