      <AuthProvider
        evergreenAppURL="https://mock-evergreen.example.com"
        remoteAuthURL="https://mock-auth.example.com"
        localAuthRoute="/login"
        shouldUseLocalAuth={true}
      >
        <Story />
      </AuthProvider>
    ),
  ],
