  1→import {
  2→  Exception,
  3→  Span,
  4→  SpanStatusCode,
  5→  context,
  6→  trace,
  7→} from "@opentelemetry/api";
  8→
  9→/**
 10→ * `streamedFetch` is a utility function that exposes a `ReadableStream` from
 11→ * the response body of a `fetch` request. This allows us to stream the response
 12→ * body and process it as it comes in, rather than waiting for the entire response.
 13→ * The function is instrumented with OpenTelemetry to record spans for the
 14→ * fetch and streaming operations.
 15→ * @param url - the url to fetch
 16→ * @param options - an object containing options for the fetch request
 17→ * @param parentSpan - the OpenTelemetry span to use for tracing
 18→ * @returns a `ReadableStream` from the response body
 19→ */
 20→
 21→enum IncompleteDownloadReason {
 22→  ServerError = "SERVER_ERROR",
 23→  FileTooLarge = "FILE_TOO_LARGE",
 24→}
 25→
 26→export type StreamedFetchOptions = {
 27→  abortController?: AbortController;
 28→  onProgress?: (progress: number) => void;
 29→  onIncompleteDownload?: (
 30→    reason: IncompleteDownloadReason,
 31→    error?: Error,
 32→  ) => void;
 33→  downloadSizeLimit?: number;
 34→  logLineSizeLimit?: number;
 35→};
 36→
 37→export const streamedFetch = async (
 38→  url: string,
 39→  options: StreamedFetchOptions,
 40→  parentSpan: Span,
 41→) => {
 42→  const tracer = trace.getTracer("default");
 43→
 44→  try {
 45→    return await context.with(
 46→      trace.setSpan(context.active(), parentSpan),
 47→      async () => {
 48→        const streamedFetchSpan = tracer.startSpan("streamedFetch");
 49→        try {
 50→          const response = await fetch(url, {
 51→            credentials: "include",
 52→            signal: options.abortController
 53→              ? options.abortController.signal
 54→              : undefined,
 55→          });
 56→
 57→          if (!response.ok) {
 58→            const errMsg = `Network response was not ok (${response.status})`;
 59→            streamedFetchSpan.setStatus({
 60→              code: SpanStatusCode.ERROR,
 61→              message: errMsg,
 62→            });
 63→            throw new Error(errMsg);
 64→          }
 65→
 66→          if (!response.body) {
 67→            const errMsg = "Network response has no body";
 68→            streamedFetchSpan.setStatus({
 69→              code: SpanStatusCode.ERROR,
 70→              message: errMsg,
 71→            });
 72→            throw new Error(errMsg);
 73→          }
 74→
 75→          const reader = response.body.getReader();
 76→          let bytesFetched = 0;
 77→
 78→          const stream = new ReadableStream({
 79→            async start(controller) {
 80→              streamedFetchSpan.addEvent("streamedFetchStart", { url });
 81→              try {
 82→                while (true) {
 83→                  if (
 84→                    options?.downloadSizeLimit &&
 85→                    bytesFetched > options.downloadSizeLimit
 86→                  ) {
 87→                    options?.onIncompleteDownload?.(
 88→                      IncompleteDownloadReason.FileTooLarge,
 89→                    );
 90→                    controller.close();
 91→                    break;
 92→                  }
 93→                  // eslint-disable-next-line no-await-in-loop
 94→                  const { done, value } = await reader.read();
 95→                  if (done) {
 96→                    controller.close();
 97→                    break;
 98→                  }
 99→                  if (bytesFetched === 0) {
100→                    // Record the first chunk received as an event
101→                    streamedFetchSpan.addEvent("first chunk received", {
102→                      chunkSize: value?.length ?? 0,
103→                    });
104→                  }
105→                  options?.onProgress?.(value?.length ?? 0);
106→                  bytesFetched += value?.length ?? 0;
107→
108→                  controller.enqueue(value);
109→                }
110→              } catch (error) {
111→                // If we've already fetched some bytes, call onIncompleteDownload
112→                if (bytesFetched > 0) {
113→                  options?.onIncompleteDownload?.(
114→                    IncompleteDownloadReason.ServerError,
115→                    error as Error,
116→                  );
117→                  controller.close();
118→                } else {
119→                  controller.error(error);
120→                }
121→                streamedFetchSpan.recordException(error as Exception);
122→                streamedFetchSpan.setAttribute("bytes_fetched", bytesFetched);
123→                streamedFetchSpan.setStatus({
124→                  code: SpanStatusCode.ERROR,
125→                  message: (error as Error).message,
126→                });
127→              } finally {
128→                streamedFetchSpan.addEvent("streamedFetchEnd", {
129→                  bytes_fetched: bytesFetched,
130→                });
131→                streamedFetchSpan.setAttribute("bytes_fetched", bytesFetched);
132→                streamedFetchSpan.end();
133→                reader.releaseLock();
134→              }
135→            },
136→          });
137→
138→          return stream;
139→        } catch (error) {
140→          streamedFetchSpan.recordException(error as Exception);
141→          streamedFetchSpan.setStatus({
142→            code: SpanStatusCode.ERROR,
143→            message: (error as Error).message,
144→          });
145→          streamedFetchSpan.end();
146→          throw error;
147→        }
148→      },
149→    );
150→  } catch (error) {
151→    parentSpan.recordException(error as Exception);
152→    parentSpan.setStatus({
153→      code: SpanStatusCode.ERROR,
154→      message: (error as Error).message,
155→    });
156→    parentSpan.end();
157→    throw error;
158→  }
159→};
