import { http, HttpResponse } from 'msw';

export const mswHandlers = {
  auth: [
    http.post('*/graphql/query', async ({ request }) => {
      const body = (await request.json()) as { query?: string };
      if (body?.query?.includes('user')) {
        return HttpResponse.json({
          data: {
            user: {
              userId: 'mock-user-id',
            },
          },
        });
      }
      return HttpResponse.json({ data: {} });
    }),
    http.post('*/login', () => {
      return HttpResponse.json({ ok: true }, { status: 200 });
    }),
    http.get('*/logout', () => {
      return new HttpResponse(null, { status: 200 });
    }),
  ],
};

import type { Preview } from '@storybook/react-vite';
import { Global } from '@emotion/react';
import { MemoryRouter } from 'react-router-dom';
import { initialize, mswLoader } from 'msw-storybook-addon';
import { ToastProvider } from '../src/context/toast';
import { resetStyles, bodyStyles } from '../src/components/styles/globalStyles';
import { mswHandlers } from './msw-handlers';

initialize({
  onUnhandledRequest: 'bypass',
});

const preview: Preview = {
  decorators: [
    (Story) => (
      <MemoryRouter>
        <Global styles={resetStyles} />
        <Global styles={bodyStyles} />
        <ToastProvider>
          <Story />
        </ToastProvider>
      </MemoryRouter>
    ),
  ],
  loaders: [mswLoader],
  parameters: {
    controls: {
      matchers: {
        color: /(background|color)$/i,
        date: /Date$/i,
      },
    },
    a11y: {
      test: 'todo',
    },
    msw: {
      handlers: mswHandlers,
    },
  },
};

export default preview;

import type { Meta, StoryObj } from '@storybook/react-vite';
import { expect, waitFor } from 'storybook/test';
import Accordion, { AccordionCaretAlign, AccordionCaretIcon } from './index';

const meta = {
  component: Accordion,
  tags: ['ai-generated'],
  args: {
    title: 'Accordion Title',
    children: <div>Accordion content goes here with some details about the item.</div>,
  },
} satisfies Meta<typeof Accordion>;

export default meta;
type Story = StoryObj<typeof meta>;

export const Default: Story = {
  play: async ({ canvas }) => {
    await expect(canvas.getByText('Accordion Title')).toBeVisible();
    await expect(canvas.getByLabelText('Accordion icon')).toBeVisible();
  },
};

export const DefaultOpen: Story = {
  args: {
    defaultOpen: true,
  },
  play: async ({ canvas }) => {
    await expect(canvas.getByText('Accordion Title')).toBeVisible();
    await expect(canvas.getByText('Accordion content goes here with some details about the item.')).toBeVisible();
  },
};

export const WithSubtitle: Story = {
  args: {
    defaultOpen: true,
    subtitle: <span>This is a subtitle</span>,
  },
